result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_gencode.py", "content": "from gencode import CODON_TABLE, STOP, aa_to_codons, codons_per_aa, degeneracy_census


def test_sense_and_stop_counts():
    counts = codons_per_aa()
    assert sum(counts.values()) == 64
    assert counts[STOP] == 3
    sense = sum(n for aa, n in counts.items() if aa != STOP)
    assert sense == 61
    assert len(CODON_TABLE) == 64  # all codons present, no duplicates


def test_exactly_L_S_R_have_6():
    counts = codons_per_aa()
    sixfold = {aa for aa, n in counts.items() if n == 6}
    assert sixfold == {"L", "S", "R"}


def test_exactly_M_W_have_1():
    counts = codons_per_aa()
    onefold = {aa for aa, n in counts.items() if n == 1}
    assert onefold == {"M", "W"}


def test_degeneracy_census():
    census = degeneracy_census()
    assert census == {1: 2, 2: 9, 3: 1, 4: 5, 6: 3}
    # I is the only 3-fold amino acid
    rev = aa_to_codons()
    assert {aa for aa, cs in rev.items() if len(cs) == 3} == {"I"}
    # sanity: total amino acids including stop = 21
    assert sum(census.values()) == 21


def test_reverse_table_disjoint_union_61():
    rev = aa_to_codons()
    lists = list(rev.values())
    union = [c for cs in lists for c in cs]
    assert len(union) == len(set(union))          # disjoint
    assert set(union) == set(CODON_TABLE.keys()) - {
        c for c, aa in CODON_TABLE.items() if aa == STOP
    }
    assert len(union) == 61                       # union has 61 codons
